from lessons_1 import lesson

lesson("what-is-a-bond", 2, 5, None, [0, 2, 1],
 en=dict(t="What a bond is", s="A bond is a loan you make to a government or company in exchange for interest (coupons) and repayment at maturity.",
  sec=[("Lending instead of owning", "A bond has a face value, a coupon rate and a maturity date. The issuer promises to pay the coupons and return the face value at maturity. Bondholders do not own the issuer; they are creditors and are repaid before shareholders if the issuer gets into trouble."),
       ("Risks of bonds", "The main risks are default (the issuer cannot pay), interest rates (when market rates rise, existing bonds with lower coupons fall in price), inflation (fixed payments buy less) and liquidity. Credit ratings summarise default risk but can be wrong or change. If you hold a high-quality bond to maturity, interim price swings do not change the payments you were promised.")],
  a="Buying a bond is like lending money to a friend with a written promise: regular interest and the full amount back on a set date — as long as the friend can pay.",
  k=["Bondholders are lenders, not owners.", "Bond prices fall when market interest rates rise.", "Default risk depends on the issuer; ratings summarise it imperfectly."],
  q=[("What happens to existing bond prices when market interest rates rise?", ["They usually fall", "They usually rise", "Nothing"], "New bonds pay more, so older bonds with lower coupons become less attractive."),
     ("What does a credit rating describe?", ["The expected share price", "The coupon rate", "An agency's view of default risk"], "Ratings are opinions about the issuer's ability to pay."),
     ("Who is repaid first if a company fails?", ["Shareholders", "Bondholders", "Both equally"], "Creditors such as bondholders rank ahead of shareholders.")]),
 ru=dict(t="Что такое облигация", s="Облигация — это заём государству или компании в обмен на проценты (купоны) и возврат номинала при погашении.",
  sec=[("Даёте в долг, а не владеете", "У облигации есть номинал, ставка купона и дата погашения. Эмитент обещает платить купоны и вернуть номинал при погашении. Держатели облигаций не владеют эмитентом — они кредиторы и получают деньги раньше акционеров, если у эмитента проблемы."),
       ("Риски облигаций", "Главные риски — дефолт (эмитент не может платить), процентный риск (при росте рыночных ставок старые облигации с низким купоном дешевеют), инфляция (фиксированные выплаты обесцениваются) и ликвидность. Кредитные рейтинги обобщают риск дефолта, но могут ошибаться и меняться. Если держать качественную облигацию до погашения, промежуточные колебания цены не меняют обещанных выплат.")],
  a="Купить облигацию — как одолжить другу деньги под расписку: регулярные проценты и полная сумма в оговорённый день — если друг сможет заплатить.",
  k=["Держатели облигаций — кредиторы, а не владельцы.", "Цены облигаций падают при росте рыночных ставок.", "Риск дефолта зависит от эмитента; рейтинги отражают его неидеально."],
  q=[("Что происходит с ценами старых облигаций при росте рыночных ставок?", ["Обычно падают", "Обычно растут", "Ничего"], "Новые облигации платят больше, поэтому старые с низким купоном менее привлекательны."),
     ("Что описывает кредитный рейтинг?", ["Ожидаемую цену акции", "Ставку купона", "Мнение агентства о риске дефолта"], "Рейтинг — это мнение о способности эмитента платить."),
     ("Кто получает деньги первым при банкротстве компании?", ["Акционеры", "Держатели облигаций", "Все поровну"], "Кредиторы, например держатели облигаций, стоят в очереди раньше акционеров.")]),
 cs=dict(t="Co je dluhopis", s="Dluhopis je půjčka státu nebo firmě výměnou za úroky (kupony) a splacení jmenovité hodnoty při splatnosti.",
  sec=[("Půjčujete, nevlastníte", "Dluhopis má jmenovitou hodnotu, kupónovou sazbu a datum splatnosti. Emitent slibuje vyplácet kupony a vrátit jmenovitou hodnotu při splatnosti. Držitelé dluhopisů emitenta nevlastní; jsou to věřitelé a dostanou zaplaceno před akcionáři, pokud má emitent potíže."),
       ("Rizika dluhopisů", "Hlavní rizika jsou úpadek (emitent nemůže platit), úrokové riziko (když tržní sazby rostou, starší dluhopisy s nižším kuponem zlevní), inflace (pevné platby mají menší kupní sílu) a likvidita. Ratingy shrnují riziko úpadku, ale mohou se mýlit nebo změnit. Pokud kvalitní dluhopis držíte do splatnosti, průběžné výkyvy ceny nemění slíbené platby.")],
  a="Koupit dluhopis je jako půjčit kamarádovi peníze na dlužní úpis: pravidelné úroky a celá částka zpět v daný den — pokud kamarád bude mít z čeho platit.",
  k=["Držitelé dluhopisů jsou věřitelé, ne vlastníci.", "Ceny dluhopisů klesají, když rostou tržní úrokové sazby.", "Riziko úpadku závisí na emitentovi; ratingy ho shrnují nedokonale."],
  q=[("Co se stane s cenami existujících dluhopisů, když tržní sazby vzrostou?", ["Obvykle klesnou", "Obvykle vzrostou", "Nic"], "Nové dluhopisy platí víc, takže starší s nižším kuponem jsou méně atraktivní."),
     ("Co popisuje úvěrový rating?", ["Očekávanou cenu akcie", "Kupónovou sazbu", "Názor agentury na riziko úpadku"], "Ratingy jsou názory na schopnost emitenta platit."),
     ("Kdo dostane peníze první, když firma zkrachuje?", ["Akcionáři", "Držitelé dluhopisů", "Oba stejně"], "Věřitelé, jako držitelé dluhopisů, mají přednost před akcionáři.")]))

lesson("what-is-an-etf", 2, 5, None, [2, 1, 0],
 en=dict(t="What an ETF is", s="An exchange-traded fund (ETF) is a fund that holds many securities and trades on an exchange like a share.",
  sec=[("Many securities in one", "Most ETFs track an index, for example a world stock index or a government bond index. One purchase gives you a small slice of hundreds or thousands of securities, which spreads company-specific risk. In the EU, funds sold to private investors are usually UCITS funds with a Key Information Document (KID)."),
       ("What to check", "Look at the ongoing charges (TER), what the index contains, the fund's currency exposure (often different from its trading currency), whether it distributes or accumulates income, the replication method (physical or synthetic) and the fund size. An ETF still falls when its market falls — diversification reduces some risks but not market risk.")],
  a="An ETF is like a ready-made fruit basket: instead of choosing every fruit yourself, you buy a basket assembled by a published recipe.",
  k=["An ETF spreads money across many securities in one trade.", "It still carries the risk of its whole market.", "Costs, index, currency exposure and replication method matter."],
  q=[("What risk does an ETF on a broad index reduce?", ["Market risk", "Inflation risk", "The risk of a single company failing"], "Spreading across many companies reduces company-specific risk, not the risk of the whole market."),
     ("What is the TER?", ["The fund's tax rate", "The fund's ongoing annual costs", "The trading hours"], "The total expense ratio is deducted from the fund every year."),
     ("Which document describes an EU retail fund's key facts?", ["The KID", "The annual tax return", "The broker's advert"], "UCITS funds must provide a Key Information Document.")]),
 ru=dict(t="Что такое ETF", s="Биржевой фонд (ETF) — фонд, который держит множество ценных бумаг и торгуется на бирже как акция.",
  sec=[("Много бумаг в одной", "Большинство ETF следуют за индексом, например мировым индексом акций или индексом гособлигаций. Одной покупкой вы получаете маленькую долю сотен или тысяч бумаг, что распределяет риск отдельных компаний. В ЕС фонды для частных инвесторов обычно являются фондами UCITS с документом ключевой информации (KID)."),
       ("Что проверять", "Смотрите на текущие расходы (TER), состав индекса, валютную экспозицию фонда (часто отличается от валюты торгов), распределяет ли он доход или реинвестирует, метод репликации (физический или синтетический) и размер фонда. ETF всё равно падает, когда падает его рынок: диверсификация снижает часть рисков, но не рыночный риск.")],
  a="ETF — как готовая фруктовая корзина: вместо выбора каждого фрукта вы покупаете корзину, собранную по опубликованному рецепту.",
  k=["ETF распределяет деньги по множеству бумаг одной сделкой.", "Он всё равно несёт риск всего своего рынка.", "Важны расходы, индекс, валютная экспозиция и метод репликации."],
  q=[("Какой риск снижает ETF на широкий индекс?", ["Рыночный риск", "Инфляционный риск", "Риск краха отдельной компании"], "Распределение по многим компаниям снижает риск отдельной компании, но не риск всего рынка."),
     ("Что такое TER?", ["Налоговая ставка фонда", "Текущие годовые расходы фонда", "Часы торгов"], "Коэффициент совокупных расходов ежегодно вычитается из фонда."),
     ("Какой документ описывает ключевые сведения о розничном фонде в ЕС?", ["KID", "Годовая налоговая декларация", "Реклама брокера"], "Фонды UCITS обязаны предоставлять документ ключевой информации.")]),
 cs=dict(t="Co je ETF", s="Burzovně obchodovaný fond (ETF) drží mnoho cenných papírů a obchoduje se na burze jako akcie.",
  sec=[("Mnoho cenných papírů v jednom", "Většina ETF sleduje index, například světový akciový index nebo index státních dluhopisů. Jedním nákupem získáte malý podíl na stovkách až tisících cenných papírů, což rozkládá riziko jednotlivých firem. V EU jsou fondy pro drobné investory obvykle fondy UCITS se sdělením klíčových informací (KID)."),
       ("Co ověřit", "Sledujte průběžné náklady (TER), složení indexu, měnovou expozici fondu (často jinou než měna obchodování), zda výnosy vyplácí nebo reinvestuje, metodu replikace (fyzická nebo syntetická) a velikost fondu. ETF přesto klesá, když klesá jeho trh — diverzifikace snižuje některá rizika, ale ne tržní riziko.")],
  a="ETF je jako hotový koš ovoce: místo výběru každého kusu koupíte koš sestavený podle zveřejněného receptu.",
  k=["ETF rozloží peníze do mnoha cenných papírů jedním obchodem.", "Stále nese riziko celého svého trhu.", "Záleží na nákladech, indexu, měnové expozici a metodě replikace."],
  q=[("Jaké riziko snižuje ETF na široký index?", ["Tržní riziko", "Inflační riziko", "Riziko krachu jedné firmy"], "Rozložení do mnoha firem snižuje riziko jednotlivé firmy, ne riziko celého trhu."),
     ("Co je TER?", ["Daňová sazba fondu", "Průběžné roční náklady fondu", "Obchodní hodiny"], "Celková nákladovost se z fondu strhává každý rok."),
     ("Který dokument popisuje klíčové údaje fondu pro drobné investory v EU?", ["KID", "Roční daňové přiznání", "Reklama brokera"], "Fondy UCITS musí poskytovat sdělení klíčových informací.")]))

lesson("how-prices-form", 2, 4, None, [1, 0, 2],
 en=dict(t="How stock prices are determined", s="Prices come from orders: a trade happens when a buyer's price meets a seller's price.",
  sec=[("Supply, demand and the order book", "The exchange keeps an order book of bids (prices buyers offer) and asks (prices sellers want). The gap between the best bid and the best ask is the spread. When more people want to buy than sell at current prices, the price tends to rise until enough sellers appear — and the reverse."),
       ("Information and expectations", "Investors buy or sell when their view of a company's future changes: results, interest rates, news, or simply mood. Because prices already include what is widely known, a good piece of news may not move the price if it was expected. Short-term moves are often noise; nobody can reliably predict them.")],
  a="It works like an auction that never ends: the price is wherever the most eager buyer and the most eager seller currently agree.",
  k=["Prices form where buyers' and sellers' orders meet.", "The spread is the gap between the best buy and sell prices.", "Expected news is often already in the price."],
  q=[("What is the spread?", ["The commission of the broker", "The difference between the best bid and the best ask", "The daily price change"], "A wide spread is an extra cost when you trade."),
     ("Why might a share not rise after good results?", ["The results were already expected and priced in", "Exchanges forbid rises after results", "Good results always lower prices"], "Prices reflect expectations, not only news."),
     ("Can short-term price moves be predicted reliably?", ["Yes, with chart patterns", "Yes, by experts", "No, they are largely unpredictable"], "Short-term moves are dominated by new information and noise.")]),
 ru=dict(t="Как формируются цены акций", s="Цены возникают из заявок: сделка происходит, когда цена покупателя встречается с ценой продавца.",
  sec=[("Спрос, предложение и книга заявок", "Биржа ведёт книгу заявок: заявки на покупку (bid — цены, которые предлагают покупатели) и на продажу (ask — цены, которые хотят продавцы). Разница между лучшей ценой покупки и продажи — спред. Когда по текущим ценам больше желающих купить, чем продать, цена обычно растёт, пока не появятся продавцы, — и наоборот."),
       ("Информация и ожидания", "Инвесторы покупают или продают, когда меняется их взгляд на будущее компании: отчётность, ставки, новости или просто настроение. Поскольку цены уже учитывают общеизвестное, хорошая новость может не сдвинуть цену, если её ждали. Краткосрочные колебания часто являются шумом, и никто не может надёжно их предсказать.")],
  a="Это похоже на бесконечный аукцион: цена там, где сейчас договорились самый активный покупатель и самый активный продавец.",
  k=["Цена формируется там, где встречаются заявки покупателей и продавцов.", "Спред — разница между лучшими ценами покупки и продажи.", "Ожидаемые новости часто уже учтены в цене."],
  q=[("Что такое спред?", ["Комиссия брокера", "Разница между лучшей ценой покупки и продажи", "Дневное изменение цены"], "Широкий спред — дополнительный расход при сделке."),
     ("Почему акция может не вырасти после хорошей отчётности?", ["Результаты уже ожидались и были учтены в цене", "Биржи запрещают рост после отчётов", "Хорошие результаты всегда снижают цену"], "Цены отражают ожидания, а не только новости."),
     ("Можно ли надёжно предсказать краткосрочные колебания?", ["Да, по графическим фигурам", "Да, это умеют эксперты", "Нет, они в основном непредсказуемы"], "Краткосрочные движения определяются новой информацией и шумом.")]),
 cs=dict(t="Jak vznikají ceny akcií", s="Ceny vznikají z pokynů: obchod proběhne, když se cena kupujícího setká s cenou prodávajícího.",
  sec=[("Nabídka, poptávka a kniha pokynů", "Burza vede knihu pokynů s nákupními nabídkami (bid — ceny, které nabízejí kupující) a prodejními (ask — ceny, které chtějí prodávající). Rozdíl mezi nejlepší nákupní a prodejní cenou je spread. Když chce za současné ceny víc lidí koupit než prodat, cena obvykle roste, dokud se neobjeví prodávající — a naopak."),
       ("Informace a očekávání", "Investoři nakupují nebo prodávají, když se změní jejich pohled na budoucnost firmy: výsledky, úrokové sazby, zprávy nebo jen nálada. Protože ceny už obsahují, co je obecně známo, dobrá zpráva cenu nemusí pohnout, pokud se čekala. Krátkodobé pohyby jsou často šum; nikdo je spolehlivě nepředpoví.")],
  a="Funguje to jako nekonečná aukce: cena je tam, kde se právě dohodl nejochotnější kupující s nejochotnějším prodávajícím.",
  k=["Ceny vznikají tam, kde se potkají pokyny kupujících a prodávajících.", "Spread je rozdíl mezi nejlepší nákupní a prodejní cenou.", "Očekávané zprávy už často jsou v ceně."],
  q=[("Co je spread?", ["Provize brokera", "Rozdíl mezi nejlepší nákupní a prodejní cenou", "Denní změna ceny"], "Široký spread je při obchodu dodatečný náklad."),
     ("Proč akcie nemusí po dobrých výsledcích vzrůst?", ["Výsledky se čekaly a už byly v ceně", "Burzy po výsledcích růst zakazují", "Dobré výsledky vždy snižují cenu"], "Ceny odrážejí očekávání, ne jen zprávy."),
     ("Lze krátkodobé pohyby cen spolehlivě předpovědět?", ["Ano, podle grafických formací", "Ano, umí to experti", "Ne, jsou z velké části nepředvídatelné"], "Krátkodobé pohyby určují nové informace a šum.")]))
